### SVC#librariesimport numpy as npimport pandas as pdimport matplotlib.pyplot as pltfrom sklearn.model_selection import train_test_splitfrom sklearn.preprocessing import StandardScalerfrom sklearn.preprocessing import LabelEncoderfrom sklearn.svm import SVCfrom matplotlib.colors import ListedColormapfrom sklearn.metrics import accuracy_score#plot decision regions function def plot_decision_regions(X, y, classifier, resolution=0.02):    # setup marker generator and color map    markers = ('o', 's', '^', 'v', '<')    colors = ('red', 'blue', 'lightgreen', 'gray', 'cyan')    cmap = ListedColormap(colors[:len(np.unique(y))])    # plot the decision surface    x1_min, x1_max = X[:, 0].min() - 1, X[:, 0].max() + 1    x2_min, x2_max = X[:, 1].min() - 1, X[:, 1].max() + 1    xx1, xx2 = np.meshgrid(np.arange(x1_min, x1_max, resolution),                           np.arange(x2_min, x2_max, resolution))    lab = classifier.predict(np.array([xx1.ravel(), xx2.ravel()]).T)    lab = lab.reshape(xx1.shape)    plt.contourf(xx1, xx2, lab, alpha=0.3, cmap=cmap)    plt.xlim(xx1.min(), xx1.max())    plt.ylim(xx2.min(), xx2.max())    # plot class examples    for idx, cl in enumerate(np.unique(y)):        plt.scatter(x=X[y == cl, 0],                     y=X[y == cl, 1],                    alpha=0.8,                     c=colors[idx],                    marker=markers[idx],                     label=f'Class {cl}',                     edgecolor='black')#read in dataclownfish_data = pd.read_excel('/Users/ggraham/Desktop/multiome_poa/Reference/Complete Data Frame (Hormones, Behavior, Size, Gonads) GG.xlsx')clownfish_data_known_sex = clownfish_data[(clownfish_data['Status'].isin(['M','F']))]clown_x = clownfish_data_known_sex[['mass_final_cm','Log_11KT']]clown_x['Log_11KT'][9] = clownfish_data_known_sex['Log_11KT'][clownfish_data_known_sex['Status']=='M'].mean()clown_x['Log_11KT'][8] = clownfish_data_known_sex['Log_11KT'][clownfish_data_known_sex['Status']=='F'].mean()clown_y = clownfish_data_known_sex[['Status']]    # encode labelsle = LabelEncoder()y_encoded = le.fit_transform(clown_y.values.ravel())# Now perform the train-test split with the encoded labelsX_train, X_test, y_train, y_test = train_test_split(clown_x,                                                    y_encoded,                                                    test_size = 0.3,                                                     random_state =1,                                                     stratify = y_encoded)# scalesc = StandardScaler()sc.fit(X_train)x_train_std = sc.transform(X_train)x_test_std = sc.transform(X_test)# make x and y combinedX_combined_std = np.vstack((x_train_std, x_test_std))y_combined = np.hstack((y_train, y_test))"""In SVM's, the goal is to maximize the margin, the distane the hyperplane is fromthe boundaries of the points it is definingBecause I don't believe my variables are perfectly linearly separable (m and f are butdominants are not, I want to use slack variables with a smaller parameter C)"""#svm timesvm = SVC(kernel = 'rbf', #this wasnt the one in the example but an AI recommended I use it          #for my final goal          C = 10,           random_state = 1,          gamma=0.10          )svm.fit(x_train_std, y_train)plot_decision_regions(X_combined_std,                       y_combined,                       classifier =svm) ### oooh interesting shape### now test with dominants#separate dominant and non dominant dataclownfish_data_d = clownfish_data[(clownfish_data['Status'].isin(['D','E','NF']))]clownfish_data_m_f = clownfish_data[(clownfish_data['Status'].isin(['M','F']))]#fill in missing values and make an x matrixclown_mf_x = clownfish_data_m_f[['mass_final_cm','Log_11KT']]clown_mf_x['Log_11KT'][9] = clownfish_data_m_f['Log_11KT'][clownfish_data_m_f['Status']=='M'].mean()clown_mf_x['Log_11KT'][8] = clownfish_data_m_f['Log_11KT'][clownfish_data_m_f['Status']=='F'].mean()clown_d_x = clownfish_data_d[['mass_final_cm','Log_11KT']]#make labels clown_y_mf = clownfish_data_m_f[['Status']]    le = LabelEncoder()clown_y_mf = le.fit_transform(clown_y_mf.values.ravel())dom_labels = clownfish_data_d[['Status']]#scale datasc = StandardScaler()sc.fit(clown_mf_x)mf_std = sc.transform(clown_mf_x)dom_std = sc.transform(clown_d_x)                                    svm_d = SVC(kernel = 'rbf',           C = 10,           random_state = 1,          gamma=0.1          )svm_d.fit(mf_std, clown_y_mf)dom_predictions=svm_d.predict(dom_std)dom_labelsdom_labels['Prediction'] =dom_predictionsplot_decision_regions(mf_std,                       clown_y_mf,                       classifier =svm_d) ### oooh interesting shapeplt.scatter(x=dom_std[:,0],            y=dom_std[:,1],            c=dom_labels['Status'].astype('category').cat.codes,            cmap='viridis',            marker ='^' )plt.xlabel('Standardized Mass')plt.ylabel('Standardized Log_11KT')plt.legend(loc='upper right')plt.show()             clownfish_data.loc[30]                                                                      